PART 3: Reverse a String

#include <stdio.h>

int main() {
    char str[100];
    int i, len = 0;
    char temp;

    printf("Enter a string: ");
    scanf("%s", str);

    // Find length
    while (str[len] != '\0') len++;

    // Swap characters from both ends
    for (i = 0; i < len / 2; i++) {
        temp = str[i];
        str[i] = str[len - 1 - i];
        str[len - 1 - i] = temp;
    }

    printf("Reversed: %s\n", str);
    return 0;
}

Sample Output:
Enter a string: Programming
Reversed: gnimmargorP

Trace for "Hello" (len=5):
i=0: swap str[0]='H' ↔ str[4]='o' → "oellH"
i=1: swap str[1]='e' ↔ str[3]='l' → "olleH"
i=2: middle — no swap needed
Result: "olleH"

PART 1: Pointer to a Function and Array Access Using Pointer

Pointer to a Function:
A function pointer is a pointer that stores the address of a function. It can be used to call functions indirectly.

Syntax: return_type (*pointer_name)(parameter_types);

Example:
#include <stdio.h>

int add(int a, int b) { return a + b; }

int main() {
    int (*fptr)(int, int);  // Declare function pointer
    fptr = add;             // Point to add function
    printf("Sum = %d\n", fptr(3, 4));  // Call via pointer: Output 7
    return 0;
}

Array Access Using Pointer:

#include <stdio.h>

int main() {
    int arr[5] = {10, 20, 30, 40, 50};
    int *ptr = arr;  // ptr points to first element
    int i;

    printf("Array elements using pointer:\n");
    for (i = 0; i < 5; i++) {
        printf("arr[%d] = %d (address: %p)\n", i, *(ptr + i), (ptr + i));
    }
    return 0;
}

Output:
arr[0] = 10
arr[1] = 20
arr[2] = 30
arr[3] = 40
arr[4] = 50

