PART 3: Dynamic Memory Allocation — Read and Write Integers

#include <stdio.h>
#include <stdlib.h>

int main() {
    int *arr, n, i;

    printf("How many integers to store? ");
    scanf("%d", &n);

    // Dynamically allocate memory for n integers
    arr = (int *)malloc(n * sizeof(int));

    if (arr == NULL) {
        printf("Memory allocation failed!\n");
        return 1;
    }

    // Write: Read values from user
    printf("Enter %d integers:\n", n);
    for (i = 0; i < n; i++) {
        printf("Enter value %d: ", i + 1);
        scanf("%d", &arr[i]);
    }

    // Read: Display values
    printf("\nStored values:\n");
    for (i = 0; i < n; i++) {
        printf("arr[%d] = %d\n", i, arr[i]);
    }

    // Free allocated memory
    free(arr);
    arr = NULL;

    printf("Memory freed successfully.\n");
    return 0;
}

Sample Output:
How many integers to store? 3
Enter 3 integers:
Enter value 1: 10
Enter value 2: 20
Enter value 3: 30

Stored values:
arr[0] = 10
arr[1] = 20
arr[2] = 30
Memory freed successfully.
